// ---------------------------------------------------------------------------
// window.storage shim — the real Claude.ai artifact preview provides this API
// natively. Outside that sandbox (this deployed site), it doesn't exist, so
// we polyfill the same shape using the browser's localStorage. Nothing else
// in this file needs to change.
// ---------------------------------------------------------------------------
if (typeof window !== "undefined" && !window.storage) {
  const nsKey = (key) => `pronahome:${key}`;
  window.storage = {
    async get(key) {
      const raw = localStorage.getItem(nsKey(key));
      if (raw === null) throw new Error("not found");
      return { key, value: raw };
    },
    async set(key, value) {
      localStorage.setItem(nsKey(key), value);
      return { key, value };
    },
    async delete(key) {
      localStorage.removeItem(nsKey(key));
      return { key, deleted: true };
    },
    async list(prefix) {
      const p = nsKey(prefix || "");
      const keys = Object.keys(localStorage).filter((k) => k.startsWith(p)).map((k) => k.slice("pronahome:".length));
      return { keys };
    },
  };
}

