const LangContext = createContext({ lang: "sq", t: STRINGS.sq, setLang: () => {} });
function useLang() { return useContext(LangContext); }

function LanguageSwitcher({ variant = "light" }) {
  const { lang, setLang } = useLang();
  const isDark = variant === "dark";
  return (
    <div style={{ display: "flex", gap: 4, background: isDark ? "rgba(255,255,255,0.12)" : "#F2EFE6", padding: 3, borderRadius: 999 }}>
      {LANGS.map((l) => {
        const active = lang === l.id;
        return (
          <button
            key={l.id}
            onClick={() => setLang(l.id)}
            style={{
              border: "none", borderRadius: 999, padding: "5px 9px", fontSize: 10.5, fontWeight: 700, cursor: "pointer",
              background: active ? (isDark ? "#fff" : NAVY) : "transparent",
              color: active ? (isDark ? NAVY : "#fff") : (isDark ? "rgba(255,255,255,0.75)" : "var(--ph-text-muted)"),
            }}
          >
            {l.label}
          </button>
        );
      })}
    </div>
  );
}

