function formatPrice(listing, t) {
  const n = Number(listing.price).toLocaleString("de-DE");
  if (listing.type !== "Qera") return `${n} €`;
  return listing.cat === "hotel" ? `${n} € ${t.perNight}` : `${n} € ${t.perMonth}`;
}
function initialsOf(name) {
  if (!name) return "PH";
  const parts = name.trim().split(/\s+/);
  return ((parts[0]?.[0] || "") + (parts[1]?.[0] || "")).toUpperCase() || "PH";
}
function resizeImageFile(file, maxWidth = 640, quality = 0.72) {
  return new Promise((resolve, reject) => {
    if (!file.type.startsWith("image/")) { reject(new Error("Not a valid image.")); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new window.Image();
      img.onload = () => {
        const scale = Math.min(1, maxWidth / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => reject(new Error("Image could not be opened."));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error("File read failed."));
    reader.readAsDataURL(file);
  });
}

