// Supabase — Phase 1: shared/public data (listings, agencies).
// Uses Supabase's REST API (PostgREST) directly via fetch, since artifacts
// can't npm-install the @supabase/supabase-js SDK. Fill in your own project's
// URL and anon (public) key below — find them in Supabase under
// Project Settings → API. The anon key is safe to embed client-side; it only
// grants whatever the Row Level Security policies allow (see supabase-schema.sql).
// ---------------------------------------------------------------------------
const SUPABASE_URL = "https://djqomrdnslnqhtffybdq.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_jJAnpgFgZ4aIu3tsi4cGDw_dN37zW22";
const SUPABASE_CONFIGURED = !SUPABASE_URL.includes("YOUR-PROJECT") && !SUPABASE_ANON_KEY.includes("YOUR-ANON");
let lastSupabaseError = null; // surfaced in a debug banner so connection issues are visible on-device, not just in devtools

async function supabaseFetch(path, options = {}) {
  const token = getAccessToken();
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...options,
    headers: {
      apikey: SUPABASE_ANON_KEY,
      "Content-Type": "application/json",
      Prefer: options.prefer || "return=representation",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {}),
    },
  });
  if (!res.ok) throw new Error(`Supabase ${res.status}: ${await res.text()}`);
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

// ---------------------------------------------------------------------------
// Supabase Auth — Phase 2: real accounts via email one-time codes.
// Same REST-only approach as the data layer above (no SDK). A session
// (access token + user) is cached in memory and persisted so it survives
// a page reload, using the same window.storage/localStorage layer as
// everything else in this file.
// ---------------------------------------------------------------------------
let currentSession = null; // { access_token, refresh_token, user }
function getAccessToken() {
  return currentSession ? currentSession.access_token : null;
}
async function authFetch(path, body) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/${path}`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error_description || data.msg || data.error || `Auth ${res.status}`);
  return data;
}
async function sendLoginCode(email) {
  // create_user: true means this doubles as sign-up on first use.
  return authFetch("otp", { email, create_user: true });
}
async function verifyLoginCode(email, code) {
  const data = await authFetch("verify", { type: "email", email, token: code });
  currentSession = { access_token: data.access_token, refresh_token: data.refresh_token, user: data.user };
  await savePersonal("session", currentSession);
  return currentSession;
}
async function restoreSession() {
  const saved = await loadPersonal("session", null);
  if (saved && saved.access_token) currentSession = saved;
  return currentSession;
}
async function signOutRemote() {
  if (!currentSession) return;
  try {
    await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
      method: "POST",
      headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${currentSession.access_token}` },
    });
  } catch (e) {}
  currentSession = null;
  await deletePersonal("session");
}

// profiles / favorites row <-> app-shape mapping (DB uses snake-ish names already close to ours)
async function loadProfileRemote(userId) {
  const rows = await supabaseFetch(`profiles?id=eq.${userId}&select=*`);
  if (!rows || !rows[0]) return null;
  const r = rows[0];
  return {
    name: r.name || "", email: r.email || "", phone: r.phone || "", avatar: r.avatar || null,
    city: r.city || "", bio: r.bio || "", company: r.company || "", accountType: r.account_type || "individual",
    emailVerified: !!r.email_verified, phoneVerified: !!r.phone_verified, createdAt: r.created_at,
  };
}
async function saveProfileRemote(userId, profile) {
  const row = {
    id: userId, name: profile.name || "", email: profile.email || "", phone: profile.phone || "",
    avatar: profile.avatar || null, city: profile.city || "", bio: profile.bio || "", company: profile.company || "",
    account_type: profile.accountType || "individual",
    email_verified: !!profile.emailVerified, phone_verified: !!profile.phoneVerified,
  };
  await supabaseFetch("profiles", { method: "POST", headers: { Prefer: "resolution=merge-duplicates,return=representation" }, body: JSON.stringify([row]) });
}
async function loadFavoritesRemote(userId) {
  const rows = await supabaseFetch(`favorites?user_id=eq.${userId}&select=listing_id`);
  return (rows || []).map((r) => r.listing_id);
}
async function addFavoriteRemote(userId, listingId) {
  await supabaseFetch("favorites", { method: "POST", body: JSON.stringify([{ user_id: userId, listing_id: listingId }]) });
}
async function removeFavoriteRemote(userId, listingId) {
  await supabaseFetch(`favorites?user_id=eq.${userId}&listing_id=eq.${encodeURIComponent(listingId)}`, { method: "DELETE" });
}

// Our JS listing objects use `desc`; the DB column is `description` (avoids
// the SQL reserved word). These two just translate between the shapes.
function listingToRow(l) {
  const { desc, ...rest } = l;
  return { ...rest, description: desc ?? "" };
}
function rowToListing(r) {
  const { description, ...rest } = r;
  return { ...rest, desc: description ?? "" };
}

// ---------------------------------------------------------------------------
// Storage helpers
// ---------------------------------------------------------------------------
async function loadSharedListings() {
  if (!SUPABASE_CONFIGURED) {
    // Fallback while Supabase isn't wired up yet, so the app still runs.
    try {
      const res = await window.storage.get("listings", true);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {}
    try { await window.storage.set("listings", JSON.stringify(SEED_LISTINGS), true); }
    catch (e) { console.error("Seeding failed", e); }
    return SEED_LISTINGS;
  }
  try {
    const rows = await supabaseFetch("listings?select=*&order=created_at.desc");
    if (rows && rows.length) return rows.map(rowToListing);
  } catch (e) { console.error("Supabase load listings failed", e); lastSupabaseError = `load: ${e.message}`; }
  // Empty table (first run) — seed it once.
  try {
    await supabaseFetch("listings", { method: "POST", body: JSON.stringify(SEED_LISTINGS.map(listingToRow)) });
  } catch (e) { console.error("Supabase seeding failed", e); lastSupabaseError = `seed: ${e.message}`; }
  return SEED_LISTINGS;
}
async function saveListingRemote(listing) {
  if (!SUPABASE_CONFIGURED) return;
  try {
    await supabaseFetch("listings", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify([listingToRow(listing)]),
    });
  } catch (e) { console.error("Supabase save listing failed", e); }
}
async function deleteListingRemote(id) {
  if (!SUPABASE_CONFIGURED) return;
  try { await supabaseFetch(`listings?id=eq.${encodeURIComponent(id)}`, { method: "DELETE" }); }
  catch (e) { console.error("Supabase delete listing failed", e); }
}
// Kept for the local (non-Supabase) fallback path only — Supabase writes go
// through saveListingRemote/deleteListingRemote per-row instead.
async function saveSharedListings(list) {
  if (SUPABASE_CONFIGURED) return;
  try { await window.storage.set("listings", JSON.stringify(list), true); }
  catch (e) { console.error("Save listings failed", e); }
}
async function loadSharedAgencies() {
  if (!SUPABASE_CONFIGURED) {
    try {
      const res = await window.storage.get("agencies", true);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {}
    try { await window.storage.set("agencies", JSON.stringify(AGENCIES), true); }
    catch (e) { console.error("Seeding agencies failed", e); }
    return AGENCIES;
  }
  try {
    const rows = await supabaseFetch("agencies?select=name&order=created_at.asc");
    if (rows && rows.length) return rows.map((r) => r.name);
  } catch (e) { console.error("Supabase load agencies failed", e); }
  try {
    await supabaseFetch("agencies", { method: "POST", body: JSON.stringify(AGENCIES.map((name) => ({ name }))) });
  } catch (e) { console.error("Supabase seeding agencies failed", e); }
  return AGENCIES;
}
async function addAgencyRemote(name) {
  if (!SUPABASE_CONFIGURED) return;
  try {
    await supabaseFetch("agencies", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify([{ name }]),
    });
  } catch (e) { console.error("Supabase add agency failed", e); }
}
async function saveSharedAgencies(list) {
  if (SUPABASE_CONFIGURED) return;
  try { await window.storage.set("agencies", JSON.stringify(list), true); }
  catch (e) { console.error("Save agencies failed", e); }
}
async function loadPersonal(key, fallback) {
  try {
    const res = await window.storage.get(key, false);
    if (res && res.value) return JSON.parse(res.value);
  } catch (e) {}
  return fallback;
}
async function savePersonal(key, value) {
  try { await window.storage.set(key, JSON.stringify(value), false); }
  catch (e) { console.error("Save personal failed", e); }
}
async function deletePersonal(key) {
  try { await window.storage.delete(key, false); } catch (e) {}
}

