function BrandMark({ size = 28 }) {
  const width = size * (160 / 211);
  return (
    <img
      src={BRAND_ICON}
      alt="PronaHome"
      style={{ height: size, width, objectFit: "contain", display: "block", flexShrink: 0 }}
    />
  );
}

const inputStyle = {
  width: "100%", border: "1px solid #E4DDCB", borderRadius: 10, padding: "10px 12px",
  fontSize: 13.5, fontFamily: "'Inter', sans-serif", color: "var(--ph-text)", background: "var(--ph-surface)", outline: "none",
};
const labelStyle = { fontSize: 12, fontWeight: 600, color: "var(--ph-text-muted)", marginBottom: 5, display: "block" };

// ---------------------------------------------------------------------------
// Onboarding / login
// ---------------------------------------------------------------------------
function OnboardingScreen({ onSubmit, onLoginWithSession }) {
  const { t } = useLang();

  // --- Real login path (Supabase configured): email -> code -> (name if new) ---
  const [step, setStep] = useState("email"); // "email" | "code" | "name"
  const [email, setEmail] = useState("");
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);

  const sendCode = async () => {
    if (!email.trim().includes("@")) { setError(t.onboardError); return; }
    setError(""); setSaving(true);
    try {
      await sendLoginCode(email.trim());
      setStep("code");
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };
  const confirmCode = async () => {
    if (code.trim().length < 6) { setError(t.wrongCode); return; }
    setError(""); setSaving(true);
    try {
      const session = await verifyLoginCode(email.trim(), code.trim());
      let profile = await loadProfileRemote(session.user.id);
      if (profile && profile.name) {
        await onLoginWithSession(session, profile);
      } else {
        setStep("name");
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };
  const finishSignup = async () => {
    if (!name.trim()) { setError(t.onboardError); return; }
    setError(""); setSaving(true);
    try {
      const profile = { name: name.trim(), email: email.trim(), emailVerified: true, accountType: "individual" };
      await saveProfileRemote(currentSession.user.id, profile);
      await onLoginWithSession(currentSession, { ...profile, createdAt: new Date().toISOString() });
    } catch (e) {
      setError(e.message);
    } finally {
      setSaving(false);
    }
  };

  // --- Local fallback path (Supabase not configured yet) ---
  const submitLocal = async () => {
    if (!name.trim() || !email.trim().includes("@")) { setError(t.onboardError); return; }
    setError(""); setSaving(true);
    await onSubmit({ name: name.trim(), email: email.trim() });
    setSaving(false);
  };

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", padding: "0 26px", background: "var(--ph-bg)", position: "relative" }}>
      <div style={{ position: "absolute", top: 18, right: 18 }}>
        <LanguageSwitcher />
      </div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 30 }}>
        <BrandMark size={40} />
        <div style={{ fontFamily: "'Poppins', sans-serif", fontWeight: 700, fontSize: 21, color: "var(--ph-text)", marginTop: 10 }}>
          Prona<span style={{ color: "var(--ph-accent)" }}>Home</span>
        </div>
        <div style={{ fontSize: 12.5, color: "var(--ph-text-muted)", marginTop: 4, textAlign: "center" }}>{t.tagline}</div>
      </div>

      {!SUPABASE_CONFIGURED ? (
        <>
          <div style={{ marginBottom: 12 }}>
            <label style={labelStyle}>{t.onboardNameLabel}</label>
            <input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder={t.onboardNamePlaceholder} />
          </div>
          <div style={{ marginBottom: 8 }}>
            <label style={labelStyle}>{t.onboardEmailLabel}</label>
            <input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder={t.onboardEmailPlaceholder} />
          </div>
          {error && <div style={{ color: "#B0473C", fontSize: 12.5, marginBottom: 8 }}>{error}</div>}
          <button
            onClick={submitLocal} disabled={saving}
            style={{ width: "100%", background: NAVY, color: "#fff", border: "none", borderRadius: 12, padding: "13px 0", fontFamily: "'Poppins', sans-serif", fontWeight: 600, fontSize: 14.5, marginTop: 10, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}
          >
            {saving ? t.onboardSubmitting : t.onboardSubmit}
          </button>
        </>
      ) : step === "email" ? (
        <>
          <div style={{ marginBottom: 8 }}>
            <label style={labelStyle}>{t.onboardEmailLabel}</label>
            <input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder={t.onboardEmailPlaceholder} />
          </div>
          {error && <div style={{ color: "#B0473C", fontSize: 12.5, marginBottom: 8 }}>{error}</div>}
          <button
            onClick={sendCode} disabled={saving}
            style={{ width: "100%", background: NAVY, color: "#fff", border: "none", borderRadius: 12, padding: "13px 0", fontFamily: "'Poppins', sans-serif", fontWeight: 600, fontSize: 14.5, marginTop: 10, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}
          >
            {saving ? t.onboardSubmitting : t.sendCodeBtn}
          </button>
        </>
      ) : step === "code" ? (
        <>
          <div style={{ fontSize: 12.5, color: "var(--ph-text-muted)", marginBottom: 12 }}>{t.codeSentTo(email)}</div>
          <label style={labelStyle}>{t.codeLabel}</label>
          <input
            style={{ ...inputStyle, textAlign: "center", letterSpacing: 4, fontSize: 16, marginBottom: 8 }}
            value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
            inputMode="numeric" maxLength={6} placeholder="000000"
          />
          {error && <div style={{ color: "#B0473C", fontSize: 12.5, marginBottom: 8 }}>{error}</div>}
          <button
            onClick={confirmCode} disabled={saving}
            style={{ width: "100%", background: NAVY, color: "#fff", border: "none", borderRadius: 12, padding: "13px 0", fontFamily: "'Poppins', sans-serif", fontWeight: 600, fontSize: 14.5, marginTop: 10, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}
          >
            {saving ? t.onboardSubmitting : t.confirmBtn}
          </button>
          <button
            onClick={() => { setStep("email"); setCode(""); setError(""); }}
            style={{ width: "100%", border: "none", background: "none", color: "var(--ph-text-muted)", fontSize: 12, marginTop: 10, cursor: "pointer" }}
          >
            {t.useAnotherEmail}
          </button>
        </>
      ) : (
        <>
          <div style={{ fontSize: 12.5, color: "var(--ph-text-muted)", marginBottom: 12 }}>{t.almostDoneHint}</div>
          <label style={labelStyle}>{t.onboardNameLabel}</label>
          <input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder={t.onboardNamePlaceholder} />
          {error && <div style={{ color: "#B0473C", fontSize: 12.5, marginTop: 8 }}>{error}</div>}
          <button
            onClick={finishSignup} disabled={saving}
            style={{ width: "100%", background: NAVY, color: "#fff", border: "none", borderRadius: 12, padding: "13px 0", fontFamily: "'Poppins', sans-serif", fontWeight: 600, fontSize: 14.5, marginTop: 10, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}
          >
            {saving ? t.onboardSubmitting : t.onboardSubmit}
          </button>
        </>
      )}
      <div style={{ fontSize: 11, color: "var(--ph-text-muted)", textAlign: "center", marginTop: 12 }}>{t.onboardTerms}</div>
    </div>
  );
}

function EditProfileScreen({ profile, onBack, onSave }) {
  const { t } = useLang();
  const [name, setName] = useState(profile.name);
  const [email, setEmail] = useState(profile.email);
  const [phone, setPhone] = useState(profile.phone || "");
  const [accountType, setAccountType] = useState(profile.accountType || "individual");
  const [company, setCompany] = useState(profile.company || "");
  const [city, setCity] = useState(profile.city || "");
  const [bio, setBio] = useState(profile.bio || "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const submit = async () => {
    if (!name.trim() || !email.trim().includes("@")) { setError(t.onboardError); return; }
    setSaving(true);
    await onSave({
      ...profile,
      name: name.trim(), email: email.trim(), phone: phone.trim(),
      accountType, company: company.trim(), city, bio: bio.trim(),
    });
    setSaving(false);
  };

  return (
    <div style={{ position: "absolute", inset: 0, background: "var(--ph-bg)", display: "flex", flexDirection: "column", zIndex: 20 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "16px 18px", borderBottom: "1px solid var(--ph-border)", background: "var(--ph-surface)" }}>
        <button onClick={onBack} style={{ border: "none", background: "none", cursor: "pointer", padding: 4 }}>
          <ChevronLeft size={20} color="var(--ph-text)" />
        </button>
        <span style={{ fontFamily: "'Poppins', sans-serif", fontWeight: 700, fontSize: 16, color: "var(--ph-text)" }}>{t.editTitle}</span>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 18 }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
          <div style={{
            width: 68, height: 68, borderRadius: "50%",
            background: profile.avatar ? `url(${profile.avatar}) center/cover no-repeat` : NAVY,
            color: "var(--ph-accent-light)", display: "flex", alignItems: "center", justifyContent: "center",
            fontFamily: "'Poppins', sans-serif", fontWeight: 700, fontSize: 22,
          }}>
            {!profile.avatar && initialsOf(profile.name)}
          </div>
        </div>

        <SettingsSection title={t.sectionAccountType}>
          <div style={{ display: "flex", gap: 8, padding: 12 }}>
            {[{ id: "individual", label: t.accountTypeIndividual }, { id: "agency", label: t.accountTypeAgency }].map((opt) => (
              <button
                key={opt.id}
                onClick={() => setAccountType(opt.id)}
                style={{
                  flex: 1, padding: "10px 0", borderRadius: 10, cursor: "pointer", fontSize: 12.5, fontWeight: 600,
                  border: accountType === opt.id ? "none" : "1px solid var(--ph-border)",
                  background: accountType === opt.id ? "var(--ph-accent)" : "transparent",
                  color: accountType === opt.id ? "#fff" : "var(--ph-text)",
                }}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </SettingsSection>

        <SettingsSection title={t.sectionBasicInfo}>
          <div style={{ padding: 14 }}>
            <label style={labelStyle}>{t.onboardNameLabel}</label>
            <input style={{ ...inputStyle, marginBottom: 12 }} value={name} onChange={(e) => setName(e.target.value)} />
            <label style={labelStyle}>{t.onboardEmailLabel}</label>
            <input style={{ ...inputStyle, marginBottom: 12 }} type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
            <label style={labelStyle}>{t.phoneLabel}</label>
            <input style={inputStyle} type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder={t.phonePlaceholder} />
          </div>
        </SettingsSection>

        <SettingsSection title={accountType === "agency" ? t.sectionProfessionalInfo : t.sectionMoreAboutYou}>
          <div style={{ padding: 14 }}>
            {accountType === "agency" && (
              <>
                <label style={labelStyle}>{t.companyLabel}</label>
                <input style={{ ...inputStyle, marginBottom: 12 }} value={company} onChange={(e) => setCompany(e.target.value)} placeholder={t.companyPlaceholder} />
              </>
            )}
            <label style={labelStyle}>{t.cityFieldLabel}</label>
            <select style={{ ...inputStyle, marginBottom: 12 }} value={city} onChange={(e) => setCity(e.target.value)}>
              <option value="">{t.allCities}</option>
              {CITY_GROUPS.map((g) => (
                <optgroup key={g.country} label={t[g.country]}>
                  {g.cities.map((c) => <option key={c} value={c}>{c}</option>)}
                </optgroup>
              ))}
            </select>
            <label style={labelStyle}>{t.bioLabel}</label>
            <textarea
              style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={bio}
              onChange={(e) => setBio(e.target.value)} placeholder={t.bioPlaceholder}
            />
          </div>
        </SettingsSection>

        {error && <div style={{ color: "#B0473C", fontSize: 12.5 }}>{error}</div>}
      </div>

      <div style={{ padding: "12px 18px calc(env(safe-area-inset-bottom, 0px) + 14px)", background: "var(--ph-surface)", borderTop: "1px solid var(--ph-border)" }}>
        <button
          onClick={submit} disabled={saving}
          style={{
            width: "100%", background: NAVY, color: "#fff", border: "none", borderRadius: 12, padding: "13px 0",
            fontFamily: "'Poppins', sans-serif", fontWeight: 600, fontSize: 14.5, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1,
          }}
        >
          {saving ? t.saving : t.saveChanges}
        </button>
      </div>
    </div>
  );
}

// A small iOS-style toggle switch, used throughout the settings screen.
function Toggle({ checked, onChange, disabled }) {
  return (
    <button
      onClick={() => !disabled && onChange(!checked)}
      disabled={disabled}
      style={{
        width: 42, height: 24, borderRadius: 999, border: "none", flexShrink: 0, position: "relative",
        background: disabled ? "#E4DDCB" : (checked ? "var(--ph-accent)" : "#D9D3C4"), cursor: disabled ? "default" : "pointer",
        transition: "background 0.15s",
      }}
    >
      <span style={{
        position: "absolute", top: 3, left: checked ? 21 : 3, width: 18, height: 18, borderRadius: "50%",
        background: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.25)", transition: "left 0.15s",
      }} />
    </button>
  );
}

