// ---------------------------------------------------------------------------
// App shell
// ---------------------------------------------------------------------------
export default function PronaHomeApp() {
  const [tab, setTab] = useState("kerko");
  const [listings, setListings] = useState([]);
  const [agencies, setAgencies] = useState(AGENCIES);
  const [favorites, setFavorites] = useState(new Set());
  const [myIds, setMyIds] = useState(new Set());
  const [profile, setProfile] = useState(null);
  const [userId, setUserId] = useState(null); // Supabase auth user id, once logged in
  const [openListing, setOpenListing] = useState(null);
  const [showNewListing, setShowNewListing] = useState(false);
  const [showMyListings, setShowMyListings] = useState(false);
  const [showEditProfile, setShowEditProfile] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAccount, setShowAccount] = useState(false);
  const [legalDoc, setLegalDoc] = useState(null);
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [showFilters, setShowFilters] = useState(false);
  const [showHotelScreen, setShowHotelScreen] = useState(false);
  const [showAgenciesScreen, setShowAgenciesScreen] = useState(false);
  const [filters, setFilters] = useState(DEFAULT_FILTERS);
  const [loading, setLoading] = useState(true);
  const [debugBanner, setDebugBanner] = useState(null);
  const [lang, setLangState] = useState("sq");
  const [accentId, setAccentId] = useState("gold");

  useEffect(() => {
    (async () => {
      try {
        const [sharedListings, sharedAgencies, savedLang, savedSettings, savedAccent] = await Promise.all([
          loadSharedListings(),
          loadSharedAgencies(),
          loadPersonal("language", "sq"),
          loadPersonal("settings", DEFAULT_SETTINGS),
          loadPersonal("accent", "gold"),
        ]);
        setListings(sharedListings);
        setAgencies(sharedAgencies);
        setLangState(savedLang || "sq");
        setSettings({ ...DEFAULT_SETTINGS, ...savedSettings });
        setAccentId(savedAccent && ACCENT_THEMES.some((a) => a.id === savedAccent) ? savedAccent : "gold");

        if (SUPABASE_CONFIGURED) {
          // Real accounts: try to restore a previously verified session.
          const session = await restoreSession();
          if (session) {
            try {
              const [remoteProfile, favIds] = await Promise.all([
                loadProfileRemote(session.user.id),
                loadFavoritesRemote(session.user.id),
              ]);
              setUserId(session.user.id);
              setProfile(remoteProfile);
              setFavorites(new Set(favIds));
            } catch (e) {
              // Session likely expired — fall back to logged-out state.
              currentSession = null;
              await deletePersonal("session");
            }
          }
        } else {
          // No Supabase yet: local-only profile/favorites, same as before.
          const [favIds, mine, savedProfile] = await Promise.all([
            loadPersonal("favorites", []),
            loadPersonal("my-listings", []),
            loadPersonal("profile", null),
          ]);
          setFavorites(new Set(favIds));
          setMyIds(new Set(mine));
          setProfile(savedProfile);
        }
      } catch (e) {
        console.error(e);
        setListings(SEED_LISTINGS);
      } finally {
        if (SUPABASE_CONFIGURED && lastSupabaseError) setDebugBanner(lastSupabaseError);
        setLoading(false);
      }
    })();
  }, []);

  // In real-account mode, "my listings" is simply every listing whose owner_id
  // matches the logged-in user — no separate list to keep in sync.
  useEffect(() => {
    if (SUPABASE_CONFIGURED && userId) {
      setMyIds(new Set(listings.filter((l) => l.owner_id === userId).map((l) => l.id)));
    }
  }, [listings, userId]);

  const setLang = (l) => {
    setLangState(l);
    savePersonal("language", l);
  };

  const toggleFav = (id) => {
    setFavorites((prev) => {
      const next = new Set(prev);
      const isRemoving = next.has(id);
      isRemoving ? next.delete(id) : next.add(id);
      if (SUPABASE_CONFIGURED && userId) {
        (isRemoving ? removeFavoriteRemote(userId, id) : addFavoriteRemote(userId, id)).catch((e) => console.error(e));
      } else {
        savePersonal("favorites", Array.from(next));
      }
      return next;
    });
  };

  const publishListing = async (newListing) => {
    // Recognize the provider by name (case-insensitive); reuse the existing
    // entry's exact casing if it matches, otherwise register it as brand new.
    const enteredAgency = (newListing.agency || "Privat").trim();
    const existingMatch = agencies.find((a) => a.toLowerCase() === enteredAgency.toLowerCase());
    const resolvedAgency = existingMatch || enteredAgency;
    const ownerId = SUPABASE_CONFIGURED && userId ? userId : (newListing.owner_id || null);
    const listingToSave = { ...newListing, agency: resolvedAgency, owner_id: ownerId };

    const nextListings = [listingToSave, ...listings];
    setListings(nextListings);

    const saves = [saveSharedListings(nextListings), saveListingRemote(listingToSave)];
    if (!SUPABASE_CONFIGURED) {
      const nextMine = new Set(myIds);
      nextMine.add(listingToSave.id);
      setMyIds(nextMine);
      saves.push(savePersonal("my-listings", Array.from(nextMine)));
    }
    if (!existingMatch) {
      const nextAgencies = [...agencies, resolvedAgency];
      setAgencies(nextAgencies);
      saves.push(saveSharedAgencies(nextAgencies), addAgencyRemote(resolvedAgency));
    }
    await Promise.all(saves);
    setShowNewListing(false);
    setTab("kerko");
  };

  const deleteListing = async (id) => {
    const nextListings = listings.filter((l) => l.id !== id);
    setListings(nextListings);
    const nextFav = new Set(favorites);
    nextFav.delete(id);
    setFavorites(nextFav);
    setOpenListing(null);

    const saves = [saveSharedListings(nextListings), deleteListingRemote(id)];
    if (SUPABASE_CONFIGURED && userId) {
      saves.push(removeFavoriteRemote(userId, id).catch(() => {}));
    } else {
      const nextMine = new Set(myIds);
      nextMine.delete(id);
      setMyIds(nextMine);
      saves.push(savePersonal("my-listings", Array.from(nextMine)), savePersonal("favorites", Array.from(nextFav)));
    }
    await Promise.all(saves);
  };

  const completeOnboarding = async (p) => {
    const withMeta = { ...p, createdAt: new Date().toISOString() };
    setProfile(withMeta);
    await savePersonal("profile", withMeta);
  };
  const onLoginWithSession = async (session, profileData) => {
    setUserId(session.user.id);
    setProfile(profileData);
    try {
      const favIds = await loadFavoritesRemote(session.user.id);
      setFavorites(new Set(favIds));
    } catch (e) { console.error(e); }
  };
  const saveProfileEdit = async (p) => {
    setProfile(p);
    if (SUPABASE_CONFIGURED && userId) await saveProfileRemote(userId, p);
    else await savePersonal("profile", p);
    setShowEditProfile(false);
  };
  const updateAvatar = async (dataUrl) => {
    const next = { ...profile, avatar: dataUrl };
    setProfile(next);
    if (SUPABASE_CONFIGURED && userId) await saveProfileRemote(userId, next);
    else await savePersonal("profile", next);
  };
  const updateSettings = async (next) => {
    setSettings(next);
    await savePersonal("settings", next);
  };
  const updateAccent = async (id) => {
    setAccentId(id);
    await savePersonal("accent", id);
  };
  const logout = async () => {
    if (SUPABASE_CONFIGURED) await signOutRemote();
    setProfile(null);
    setUserId(null);
    setFavorites(new Set());
    setMyIds(new Set());
    await deletePersonal("profile");
  };
  const deleteAccount = async () => {
    setShowAccount(false);
    if (SUPABASE_CONFIGURED && userId) {
      try { await supabaseFetch(`profiles?id=eq.${userId}`, { method: "DELETE" }); } catch (e) { console.error(e); }
      await signOutRemote();
      setUserId(null);
    } else {
      await Promise.all([savePersonal("favorites", []), savePersonal("my-listings", [])]);
    }
    setProfile(null);
    setFavorites(new Set());
    setMyIds(new Set());
    await deletePersonal("profile");
  };
  const verifyField = async (field) => {
    const next = { ...profile, [field === "email" ? "emailVerified" : "phoneVerified"]: true };
    setProfile(next);
    if (SUPABASE_CONFIGURED && userId) await saveProfileRemote(userId, next);
    else await savePersonal("profile", next);
  };

  const t = STRINGS[lang] || STRINGS.sq;
  const activeAccent = ACCENT_THEMES.find((a) => a.id === accentId) || ACCENT_THEMES[0];
  const dark = settings.darkMode;
  const palette = dark
    ? { bg: "#12151C", surface: "#1C212B", text: "#EDEFF3", textMuted: "#9099AA", border: "#2C333F", borderSoft: "#242A34" }
    : { bg: CREAM, surface: "#FFFFFF", text: INK, textMuted: MUTED, border: "#EDE7DA", borderSoft: "#F0ECE2" };

  return (
    <LangContext.Provider value={{ lang, t, setLang }}>
      <div style={{
        minHeight: "100vh", width: "100%", background: "#E7E2D6", display: "flex", alignItems: "center", justifyContent: "center",
        padding: "24px 10px", fontFamily: "'Inter', sans-serif",
        "--ph-accent": activeAccent.color, "--ph-accent-light": activeAccent.light,
        "--ph-bg": palette.bg, "--ph-surface": palette.surface, "--ph-text": palette.text,
        "--ph-text-muted": palette.textMuted, "--ph-border": palette.border, "--ph-border-soft": palette.borderSoft,
      }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700&family=Inter:wght@400;500;600&display=swap');
          * { box-sizing: border-box; }
          input::placeholder, textarea::placeholder { color: var(--ph-text-muted); }
          .spin { animation: spin 0.9s linear infinite; }
          @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
          .dual-thumb {
            position: absolute; left: 0; top: 0; width: 100%; margin: 0;
            -webkit-appearance: none; appearance: none; background: transparent; pointer-events: none;
          }
          .dual-thumb::-webkit-slider-thumb {
            -webkit-appearance: none; appearance: none; pointer-events: auto;
            width: 22px; height: 22px; border-radius: 50%; background: #fff;
            border: 2.5px solid ${NAVY}; cursor: pointer; box-shadow: 0 1px 3px rgba(15,23,41,0.25); margin-top: 0;
          }
          .dual-thumb::-moz-range-thumb {
            pointer-events: auto; width: 22px; height: 22px; border-radius: 50%; background: #fff;
            border: 2.5px solid ${NAVY}; cursor: pointer; box-shadow: 0 1px 3px rgba(15,23,41,0.25);
          }
          .dual-thumb::-webkit-slider-runnable-track { background: transparent; height: 4px; }
          .dual-thumb::-moz-range-track { background: transparent; height: 4px; }
        `}</style>

        <div style={{ width: 390, maxWidth: "100%", height: 780, maxHeight: "92vh", background: "var(--ph-bg)", borderRadius: 34, boxShadow: "0 30px 60px -20px rgba(15,23,41,0.35)", overflow: "hidden", position: "relative", display: "flex", flexDirection: "column", border: `6px solid ${NAVY_DEEP}` }}>
          {debugBanner && (
            <div style={{
              position: "absolute", top: 0, left: 0, right: 0, zIndex: 50, background: "#7A1E1E", color: "#fff",
              fontSize: 10.5, padding: "8px 10px", display: "flex", alignItems: "flex-start", gap: 8, fontFamily: "monospace",
            }}>
              <span style={{ flex: 1, wordBreak: "break-word" }}>Supabase: {debugBanner}</span>
              <button onClick={() => setDebugBanner(null)} style={{ border: "none", background: "none", color: "#fff", cursor: "pointer", flexShrink: 0 }}>
                <X size={13} />
              </button>
            </div>
          )}
          {loading ? (
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10 }}>
              <BrandMark size={34} />
              <Loader2 size={20} color={"var(--ph-accent)"} className="spin" />
              <span style={{ fontSize: 12.5, color: "var(--ph-text-muted)" }}>{t.loadingText}</span>
            </div>
          ) : !profile ? (
            <OnboardingScreen onSubmit={completeOnboarding} onLoginWithSession={onLoginWithSession} />
          ) : (
            <>
              {tab === "kerko" && (
                <SearchScreen
                  listings={listings} favorites={favorites} toggleFav={toggleFav} onOpen={setOpenListing}
                  onAddNew={() => setShowNewListing(true)} onOpenFilters={() => setShowFilters(true)}
                  onOpenHotelScreen={() => setShowHotelScreen(true)}
                  onOpenAgenciesScreen={() => setShowAgenciesScreen(true)}
                  filters={filters}
                  onQuickFilter={(partial) => setFilters((f) => ({ ...f, ...partial }))}
                />
              )}
              {tab === "preferuara" && <FavoritesScreen listings={listings} favorites={favorites} toggleFav={toggleFav} onOpen={setOpenListing} />}
              {tab === "njoftime" && <NotificationsScreen />}
              {tab === "profili" && (
                <ProfileScreen
                  profile={profile} favCount={favorites.size} myCount={myIds.size}
                  onOpenMyListings={() => setShowMyListings(true)} onAddNew={() => setShowNewListing(true)}
                  onEditProfile={() => setShowEditProfile(true)} onLogout={logout} onAvatarChange={updateAvatar}
                  onOpenSettings={() => setShowSettings(true)} onOpenAccount={() => setShowAccount(true)}
                />
              )}

              <TabBar active={tab} setActive={setTab} favCount={favorites.size} />

              {openListing && (
                <DetailScreen listing={openListing} isFav={favorites.has(openListing.id)} onToggleFav={toggleFav} onBack={() => setOpenListing(null)} isMine={myIds.has(openListing.id)} onDelete={deleteListing} />
              )}
              {showNewListing && <NewListingScreen onBack={() => setShowNewListing(false)} onPublish={publishListing} agencies={agencies} />}
              {showMyListings && (
                <MyListingsScreen listings={listings} myIds={myIds} onBack={() => setShowMyListings(false)} onOpen={(l) => { setShowMyListings(false); setOpenListing(l); }} onDelete={deleteListing} />
              )}
              {showEditProfile && <EditProfileScreen profile={profile} onBack={() => setShowEditProfile(false)} onSave={saveProfileEdit} />}
              {showSettings && (
                <SettingsScreen
                  settings={settings} onChange={updateSettings} onBack={() => setShowSettings(false)}
                  onOpenPrivacy={() => setLegalDoc("privacy")} onOpenTerms={() => setLegalDoc("terms")}
                  accentId={accentId} onAccentChange={updateAccent}
                />
              )}
              {legalDoc && <LegalDocScreen docKey={legalDoc} onBack={() => setLegalDoc(null)} />}
              {showAccount && profile && (
                <AccountScreen
                  profile={profile} favorites={favorites} myListingIds={myIds} listings={listings}
                  onBack={() => setShowAccount(false)} onDeleteAccount={deleteAccount} onVerify={verifyField}
                />
              )}
              {showFilters && <FilterScreen filters={filters} listings={listings} onBack={() => setShowFilters(false)} onApply={(f) => { setFilters(f); setShowFilters(false); }} />}
              {showHotelScreen && (
                <HotelScreen
                  listings={listings} favorites={favorites} toggleFav={toggleFav}
                  onOpen={setOpenListing} onBack={() => setShowHotelScreen(false)}
                />
              )}
              {showAgenciesScreen && (
                <AgenciesScreen
                  listings={listings} agencies={agencies} favorites={favorites} toggleFav={toggleFav}
                  onOpen={setOpenListing} onBack={() => setShowAgenciesScreen(false)}
                />
              )}
            </>
          )}
        </div>
      </div>
    </LangContext.Provider>
  );
}
